from .common import cpp,test

def syntax(number,title,prompt,body,checks,prefix='',suffix=''):
    return cpp('S',number,f'S{number:02} · {title}',prompt,[test('Поведение по контракту',body)],checks=checks,prefix=prefix,suffix=suffix,publicChecks=['Компиляция и типы','Поведение и граничные случаи'])

SCORE='class Score { int value_; public: explicit Score(int n):value_(n){} int value()const{return value_;} void add(int n){value_+=n;}\n'
syntax(1,'Сначала создаём','Напишите Score с закрытым int value_, явным конструктором из int и методом value, читающим число для const-объекта. Самостоятельно выберите полные сигнатуры. Конструктор без аргументов не требуется.', 'const Score a(7),b(-3); CHECK(a.value()==7 && b.value()==-3);', 'static_assert(!std::is_convertible_v<int,Score>); static_assert(std::is_same_v<decltype(std::declval<const Score&>().value()),int>);')
syntax(2,'Изменить оригинал','В контексте дан Score. Напишите свободную increase_by: изменить переданный оригинал на целую прибавку, без создания нового объекта. Результат не нужен.', 'Score a(4); increase_by(a,3); CHECK(a.value()==7); increase_by(a,-10); CHECK(a.value()==-3);', 'using Signature=void(*)(Score&,int); static_assert(std::is_same_v<decltype(static_cast<Signature>(&increase_by)),Signature>);',prefix=SCORE+'};\n')
syntax(3,'Операция без побочных эффектов','Вставьте в Score бинарный метод сложения. Он принимает другой Score без копирования при передаче, работает для const-операндов и возвращает независимую сумму. Для проверки поведения напишите и тело метода.', 'const Score a(2),b(9); auto c=a+b; CHECK(c.value()==11 && a.value()==2 && b.value()==9);', 'using Signature=Score(Score::*)(const Score&)const; static_assert(std::is_same_v<decltype(static_cast<Signature>(&Score::operator+)),Signature>);',prefix=SCORE,suffix='\n};\n')
syntax(4,'Составная операция','Вставьте в Score составное сложение. (a += b) += c изменяет именно a, результат обозначает текущий объект. Самосложение допустимо.', 'Score a(1); const Score b(2),c(4); CHECK(&((a+=b)+=c)==&a && a.value()==7); a+=a; CHECK(a.value()==14);','using Signature=Score&(Score::*)(const Score&); static_assert(std::is_same_v<decltype(static_cast<Signature>(&Score::operator+=)),Signature>);',prefix=SCORE,suffix='\n};\n')
syntax(5,'Левая сторона имеет значение','Score уже умеет умножаться справа на double. Напишите свободное масштабирование double * Score, используя существующую операцию. Заданная операция преобразует результат в int с отсечением дробной части.', 'const Score a(8); CHECK((2.0*a).value()==16 && (0.5*a).value()==4 && a.value()==8);', 'using Signature=Score(*)(double,const Score&); static_assert(std::is_same_v<decltype(static_cast<Signature>(&operator*)),Signature>);',prefix=SCORE+'Score operator*(double k)const{return Score(static_cast<int>(value_*k));}};\n')
syntax(6,'Равенство','Вставьте в Score константный метод сравнения по целому значению. Правый аргумент передаётся без копирования, результат имеет логический смысл.', 'const Score a(2),b(2),c(3); CHECK(a==b); CHECK(!(a==c));','using Signature=bool(Score::*)(const Score&)const; static_assert(std::is_same_v<decltype(static_cast<Signature>(&Score::operator==)),Signature>);',prefix=SCORE,suffix='\n};\n')
syntax(7,'Дружественный вывод','Вставьте friend-оператор вывода в данный Score с приватным полем. Вывод — само целое число. Работают const-объекты, любой ostream и цепочки. Объявление и реализацию восстановите самостоятельно.', 'const Score a(7); std::ostringstream out; CHECK(&(out<<a)==&out); out<<":"<<Score(-2); CHECK(out.str()=="7:-2");','static_assert(std::is_same_v<decltype(std::declval<std::ostream&>()<<std::declval<const Score&>()),std::ostream&>);',prefix='#include <ostream>\nclass Score {int value_;public:explicit Score(int n):value_(n){}\n',suffix='\n};\n')
TRIPLE='#include <cstddef>\n#include <stdexcept>\nclass Triple { int data_[3]={1,2,3}; public:\n'
syntax(8,'Индекс и присваивание','Вставьте изменяемую индексацию Triple. obj[i] = value меняет массив. Параметр — std::size_t; i>=3 бросает out_of_range, оставляя массив прежним.', 'Triple t; t[1]=9; CHECK(t[1]==9 && t[0]==1); expect_throw<std::out_of_range>([&]{t[3]=0;}); CHECK(t[1]==9);','static_assert(std::is_same_v<decltype(std::declval<Triple&>()[0]),int&>);',prefix=TRIPLE,suffix='\n};\n')
syntax(9,'Индекс и const','В контексте уже есть изменяемый []. Добавьте const-перегрузку с возвращением ссылки для чтения. Неверный индекс тоже бросает out_of_range.', 'Triple t; const Triple& c=t; t[1]=12; CHECK(c[1]==12); expect_throw<std::out_of_range>([&]{(void)c[3];});','static_assert(std::is_same_v<decltype(std::declval<const Triple&>()[0]),const int&>);',prefix=TRIPLE+'int& operator[](std::size_t i){if(i>=3)throw std::out_of_range("index");return data_[i];}\n',suffix='\n};\n')
syntax(10,'Вызов объекта','Вставьте оператор вызова Quadratic: вычислить a*x*x+b*x+c для double x, без изменения объекта. Доступен у const Quadratic, результат — double.', 'const Quadratic q(2,3,4); CHECK(q(0)==4 && q(2)==18 && q(-1)==3);','static_assert(std::is_same_v<decltype(std::declval<const Quadratic&>()(2.0)),double>);',prefix='class Quadratic{double a_,b_,c_;public:Quadratic(double a,double b,double c):a_(a),b_(b),c_(c){}\n',suffix='\n};\n')
COUNTER='class Counter{int value_;public:explicit Counter(int n):value_(n){} int value()const{return value_;}\n'
syntax(11,'Префикс','Вставьте обычный префиксный инкремент Counter. Увеличьте значение на один и верните изменённый исходный объект.', 'Counter c(5); CHECK(&(++c)==&c && c.value()==6);','static_assert(std::is_same_v<decltype(++std::declval<Counter&>()),Counter&>);',prefix=COUNTER,suffix='\n};\n')
syntax(12,'Постфикс','Вставьте обычный постфиксный инкремент Counter. Результат — независимое значение до увеличения; сам объект становится на единицу больше.', 'Counter c(5); Counter old=c++; CHECK(old.value()==5 && c.value()==6); ++c; CHECK(old.value()==5);','static_assert(std::is_same_v<decltype(std::declval<Counter&>()++),Counter>);',prefix=COUNTER+'Counter& operator++(){++value_;return *this;}\n',suffix='\n};\n')
task=syntax(13,'Вне класса','Напишите Counter с закрытым int value_, конструктором из int и value() const. Объявите reset(int) внутри класса, а определение вынесите за класс с квалификацией Counter::reset. reset меняет значение и не возвращает результат.', 'Counter c(7); c.reset(-2); CHECK(c.value()==-2); c.reset(0); CHECK(c.value()==0);','using Signature=void(Counter::*)(int); static_assert(std::is_same_v<decltype(static_cast<Signature>(&Counter::reset)),Signature>);')
task['outsideDefinition']='Counter::reset'
syntax(14,'Разбор потока','В контексте дан Point. Напишите свободный ввод из istream для формата (x,y), оба числа int. Пробелы разрешены. Неверные скобки/запятая/числа или неполный ввод: failbit и прежний объект без изменений. Верните тот же поток.', 'Point p{7,8}; std::istringstream good(" ( 3 , 4 ) "); CHECK(&(good>>p)==&good && !good.fail() && p.x==3 && p.y==4); for(const char* s:{"(3;4)","(3,)","bad"}){Point old{7,8};std::istringstream in(s);in>>old;CHECK(in.fail() && old.x==7 && old.y==8);}', 'static_assert(std::is_same_v<decltype(std::declval<std::istream&>()>>std::declval<Point&>()),std::istream&>);',prefix='#include <istream>\nstruct Point{int x,y;};\n')
